import { Splide } from '@splidejs/splide';
import { getLogger } from '~/lib/log';
import '~/lib/state/layout';

export default function announcementBarCarousel({
  autoPlay = true,
  autoPlayInterval = 5000,
  totalSlides = 1,
}) {
  const log = getLogger(this.$id('announcementBarCarousel'));

  return {
    /**
     * State
     */
    totalSlides,
    autoPlay,
    autoPlayInterval,
    lastScrollTop: 0,
    splide: null,
    scrollHandler: null,

    /**
     * Computed Properties
     */

    get hasMultipleSlides() {
      return this.totalSlides > 1;
    },

    /**
     * Lifecycle Methods
     */
    init() {
      log.debug('init', {
        totalSlides: this.totalSlides,
        autoPlay: this.autoPlay,
      });

      // Initialize Splide carousel
      this.initSplide();
    },

    destroy() {
      log.debug('destroy');

      // Clean up Splide instance
      if (this.splide) {
        this.splide.destroy();
        this.splide = null;
      }
    },

    /**
     * Initialize Splide Carousel
     */
    initSplide() {
      this.$nextTick(() => {
        const element = this.$el.querySelector('[data-splide-container]');
        if (!element) {
          log.error('Splide container element not found');
          return;
        }

        // Always initialize Splide to ensure content is visible
        // For single slides, disable all interactive features
        this.splide = new Splide(element, {
          type: this.hasMultipleSlides ? 'loop' : 'slide',
          perPage: 1,
          perMove: 1,
          gap: 0,
          pagination: false,
          arrows: false,
          autoplay: this.autoPlay && this.hasMultipleSlides,
          interval: this.autoPlayInterval,
          pauseOnHover: this.hasMultipleSlides,
          pauseOnFocus: this.hasMultipleSlides,
          resetProgress: false,
          drag: this.hasMultipleSlides,
          keyboard: this.hasMultipleSlides,
          // Disable clones for single slides to avoid duplication
          clones: this.hasMultipleSlides ? undefined : 0,
        });

        // Event handlers
        this.splide.on('moved', () => {
          log.debug('Splide moved to slide', this.splide.index);
        });

        this.splide.mount();
        log.debug('Splide initialized', {
          hasMultipleSlides: this.hasMultipleSlides,
          totalSlides: this.totalSlides,
        });
      });
    },
    /**
     * Carousel Control Methods
     */
    nextSlide() {
      if (!this.hasMultipleSlides || !this.splide) {
        return;
      }

      this.splide.go('>');
      log.debug('Next slide');
    },

    previousSlide() {
      if (!this.hasMultipleSlides || !this.splide) {
        return;
      }

      this.splide.go('<');
      log.debug('Previous slide');
    },

    goToSlide(index) {
      if (!this.hasMultipleSlides || !this.splide || index < 0 || index >= this.totalSlides) {
        return;
      }

      this.splide.go(index);
      log.debug('Go to slide', { index });
    },

    /**
     * Shopify Theme Editor Event Handlers
     */
    handleBlockSelect(event) {
      log.debug('Block selected in theme editor', event.detail);

      // Navigate to the selected block
      const blockId = event.detail?.blockId;
      if (blockId && this.splide) {
        const blockElements = this.$el.querySelectorAll('[data-block-id]');
        const blockElement = Array.from(blockElements).find(
          (el) => el.getAttribute('data-block-id') === blockId,
        );

        if (blockElement) {
          const blockIndex = Array.from(blockElements).indexOf(blockElement);
          if (blockIndex >= 0 && blockIndex < this.totalSlides) {
            this.goToSlide(blockIndex);
          }
        }
      }
    },

    handleBlockDeselect(event) {
      log.debug('Block deselected in theme editor', event.detail);
    },

    /**
     * Alpine.js Directives
     */
    directives: {
      self: {
        ':tabindex'() {
          return this.hasMultipleSlides ? '0' : '-1';
        },
        '@keydown.left.prevent'() {
          this.previousSlide();
        },
        '@keydown.right.prevent'() {
          this.nextSlide();
        },
        '@shopify:block:select'(event) {
          this.handleBlockSelect(event);
        },
        '@shopify:block:deselect'(event) {
          this.handleBlockDeselect(event);
        },
      },
    },
  };
}
